if (size <= old_size) {
	/* Zero out spare memory. */
	if (want_init_on_alloc(flags)) {
		kasan_unpoison_vmalloc((void *)p + size,
				       old_size - size,
				       KASAN_VMALLOC_PROT_NORMAL);
		memset((void *)p + size, 0, old_size - size);
	}

	kasan_poison_vmalloc((void *)p + size, old_size - size);
	kasan_unpoison_vmalloc((void *)p, size,
			       KASAN_VMALLOC_PROT_NORMAL);

	return (void *)p;
}

